     "title": "格芯获选在纽约建设两座晶圆厂，与美国商务部达成协议调整 9.55 亿美元资助并为其额外分配约 4% 股权",
     "url": "https://www.ithome.com/1/013/091.htm",
     "time": "10-14 20:48",
